# Initially generated by GitHub Copilot.

import unittest

from mb_cmn.url_percent import pct_fragment, pct_path_component


class UrlPercentTests(unittest.TestCase):
    def test_pct_path_component_encodes_space(self):
        self.assertEqual(
            pct_path_component("Song of Songs"),
            "Song%20of%20Songs",
        )

    def test_pct_path_component_encodes_canonical_hebrew_title(self):
        self.assertEqual(
            pct_path_component("ויקרא_ב/טעמים", safe="/"),
            "%D7%95%D7%99%D7%A7%D7%A8%D7%90_%D7%91/%D7%98%D7%A2%D7%9E%D7%99%D7%9D",
        )

    def test_pct_fragment_encodes_fragment_payload(self):
        self.assertEqual(
            pct_fragment("About this Edition (English Abstract)"),
            "About%20this%20Edition%20%28English%20Abstract%29",
        )


if __name__ == "__main__":
    unittest.main()
